function makeArrow(color, radius, headLen, double = false) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat);
  g.add(shaft); g.add(head);
  let head2 = null;
  if (double) { head2 = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat); g.add(head2); }
  const flip = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI);
  g.setEnds = (a, b) => {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = Math.max(dir.length(), 1e-4);
    const n = dir.clone().divideScalar(len);
    const q = new THREE.Quaternion().setFromUnitVectors(YUP, n);
    shaft.scale.set(1, len, 1);
    shaft.position.copy(a).addScaledVector(n, len / 2);
    shaft.quaternion.copy(q);
    head.position.copy(b).addScaledVector(n, -headLen / 2);
    head.quaternion.copy(q);
    if (head2) {
      head2.position.copy(a).addScaledVector(n, headLen / 2);
      head2.quaternion.copy(q.clone().multiply(flip));
    }
  };
  return g;
}

