lab('panelA', TX('(a)'), FC(1.4, -2.9, 0), { fontSize: '18px' });

// panel (b)
labB('by', IT('y'), 0.52, 1.0, { fontSize: '16px' });
labB('bx', IT('x'), -0.62, 0.06, { fontSize: '16px' });
labB('b00c', TX('(0,0)'), 0.78, 0.12, { fontSize: '13px' });
labB('bcam', TX('Camera coordinates'), 0.85, 1.2, { fontSize: '13px' });
labB('bm', IT('m'), -1.46, -0.52, { fontSize: '16px' });
labB('bn', IT('n'), -0.9, -1.34, { fontSize: '16px' });
labB('b00i', TX('(0,0)'), -1.95, -1.36, { fontSize: '13px' });
labB('bimg', TX('Image coordinates'), -0.2, -0.92, { fontSize: '13px' });
labB('bplane', TX('Virtual camera plane'), 0.7, -1.06, { fontSize: '13px' });
labB('bp', BD('p'), 0, 0.9, { fontSize: '16px', offset: [-2, 18] });
labB('panelB', TX('(b)'), 0, -1.72, { fontSize: '18px' });

/* ── fade sets ────────────────────────────────────────────────────────── */
function collect(o, arr) {
  o.traverse(n => {
    if (!n.material) return;
    const ms = Array.isArray(n.material) ? n.material : [n.material];
    ms.forEach(m => {
      if (arr.indexOf(m) === -1) {
        m.transparent = true;
        if (m.userData.base === undefined) m.userData.base = m.opacity;
        arr.push(m);
      }
    });
  });
  return arr;
}
const sets = {
  real: { mats: [], labels: ['projPlane', 'rx', 'ry', 'pR', 'fL'], a: 1, t: 1 },
  virt: { mats: [], labels: ['virtPlane', 'vx', 'vy', 'pV', 'fR'], a: 1, t: 1 }
};
collect(realGroup, sets.real.mats); collect(dotPR, sets.real.mats);
collect(fArrowL, sets.real.mats); collect(rayB, sets.real.mats);
collect(virtGroup, sets.virt.mats); collect(dotPV, sets.virt.mats);
collect(pDrop, sets.virt.mats); collect(fArrowR, sets.virt.mats);

function applyFade(set) {
  for (const m of set.mats) m.opacity = (m.userData.base === undefined ? 1 : m.userData.base) * set.a;
}

/* ── state + update ───────────────────────────────────────────────────── */
const state = { f: 1.5, fTarget: 1.5, P: { u: 4.6, v: 1.7, w: 1.1 }, panel: 'a', mode: 'both' };
const readout = document.getElementById('readout');

function refreshVis() {
  const showA = state.panel !== 'b';
  const showB = state.panel !== 'a';
  for (const e of LABELS) {
    let on = e.group === 'A' ? showA : showB;
    if (on && e.set) on = sets[e.set].a > 0.08;
    e.div.style.visibility = on ? 'visible' : 'hidden';
  }
}

function updateAll() {
  const f = state.f, u = state.P.u, v = state.P.v, w = state.P.w;
  realGroup.position.x = -f; virtGroup.position.x = f;
  realGroup.updateMatrixWorld(true); virtGroup.updateMatrixWorld(true);

  fArrowL.setEnds(new THREE.Vector3(0, 0, 0), FC(-f, 0, 0));
  fArrowR.setEnds(new THREE.Vector3(0, 0, 0), FC(f, 0, 0));

  const Pw = FC(u, v, w);
  const xc = f * w / u, yc = f * v / u;
  const pV = FC(f, yc, xc);
  const pR = FC(-f, -yc, -xc);

  dotP.position.copy(Pw); hitP.position.copy(Pw);
  dotPV.position.copy(pV); dotPR.position.copy(pR);
  rayA.setPts([Pw, pV, new THREE.Vector3(0, 0, 0)]);
  rayB.setPts([new THREE.Vector3(0, 0, 0), pR]);
  dropV.setEnds(Pw, FC(u, 0, w));
  dropH.setEnds(FC(u, 0, w), FC(u, 0, 0));
  pDrop.setEnds(pV, FC(f, 0, xc));

  L.fL.pos.copy(FC(-f / 2, 0, 0)); L.fR.pos.copy(FC(f / 2, 0, 0));
  L.projPlane.pos.copy(FC(-f, -1.45, 0)); L.virtPlane.pos.copy(FC(f, -1.45, 0));
  L.vx.pos.copy(FC(f, 0, GLEN + 0.05)); L.vy.pos.copy(FC(f, GLEN + 0.05, 0));
  L.rx.pos.copy(FC(-f, 0, -GLEN - 0.05)); L.ry.pos.copy(FC(-f, -GLEN - 0.05, 0));
  L.P.pos.copy(Pw); L.pV.pos.copy(pV); L.pR.pos.copy(pR);

  const s = BW / SIDE;
  dotB.position.set(B_ORG.x - xc * s, B_ORG.y + yc * s, 0.03);
  L.bp.local.set(dotB.position.x, dotB.position.y, 0.03);

  const px = SIDE / 640;
  const n = Math.round(380 - xc / px), m = Math.round(300 + yc / px);
  readout.innerHTML =
    `<b>P</b> = (X ${w.toFixed(2)}, Y ${v.toFixed(2)}, Z ${u.toFixed(2)})<br>` +
    `<b>p</b> cam = (x ${xc.toFixed(3)}, y ${yc.toFixed(3)})<br>` +
    `<b>p</b> pix = (n ${n}, m ${m})<br>` +
    `f = ${f.toFixed(2)}`;
}

function applyPanel(refit = true) {
  const needA = state.panel !== 'b';
  const needB = state.panel !== 'a';
  if (needA && !groupA.parent) scene.add(groupA);
  if (!needA && groupA.parent) scene.remove(groupA);
  if (needB && !groupB.parent) scene.add(groupB);
  if (!needB && groupB.parent) scene.remove(groupB);
  groupB.position.set(0, 0, 0);
  if (state.panel === 'linked') groupB.position.set(6.4, 0.8, -6.4);
  updateAll();
  if (refit) {
    if (state.panel === 'b') {
      setCameraView({ projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, heightFraction: 0.78 });
    } else {
      setCameraView({
        projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0,
        heightFraction: state.panel === 'linked' ? 0.7 : 0.62
      });
    }
  }
  refreshVis();
}

function applyMode() {
  sets.real.t = (state.mode === 'virt') ? 0 : 1;
  sets.virt.t = (state.mode === 'real') ? 0 : 1;
}

/* ── initial build ────────────────────────────────────────────────────── */
updateAll();
applyMode();
sets.real.a = sets.real.t; sets.virt.a = sets.virt.t;
applyFade(sets.real); applyFade(sets.virt);
applyPanel(true);

/* ── interactive explanations ─────────────────────────────────────────── */
registerInteractive(pinhole, {
  title: 'Pinhole (0,0,0)',
  tooltip: 'Pinhole — origin of world coordinates',
  body: 'The pinhole sits at the world origin. Every ray from a scene point to its image passes through this single point, which is why the projection is a straight line from P through (0,0,0).'
});
registerInteractive(realMesh, {
  title: 'Projection plane (real sensor)',
  tooltip: 'Real sensor at z = −f: image is inverted',
  body: 'The physical sensor lies a distance f BEHIND the pinhole, at z = −f. The image formed there is inverted in both x and y: p = (−fX/Z, −fY/Z).'
});
registerInteractive(virtMesh, {
  title: 'Virtual camera plane',
  tooltip: 'Virtual plane at z = +f: image is upright',
  body: 'Placing an identical plane a distance f IN FRONT of the pinhole gives the same geometry without inversion: p = (fX/Z, fY/Z). This is the convention used in the projection equations.'
});
registerInteractive(hitP, {
  title: 'Scene point P',
  tooltip: 'Drag me',
  body: 'Drag P to move the 3D scene point. Its image p moves as (fX/Z, fY/Z): lateral motion moves p proportionally, while increasing depth Z shrinks p toward the principal point.'
});

/* ── UI wiring ────────────────────────────────────────────────────────── */
const selPanel = document.getElementById('selPanel');
const selMode = document.getElementById('selMode');
const rngF = document.getElementById('rngF');
const fVal = document.getElementById('fVal');

selPanel.addEventListener('change', () => { state.panel = selPanel.value; applyPanel(true); });
selMode.addEventListener('change', () => { state.mode = selMode.value; applyMode(); });
rngF.addEventListener('input', () => {
  state.fTarget = parseFloat(rngF.value);
  state.f = state.fTarget;
  fVal.textContent = state.f.toFixed(2);
  updateAll();
});
document.getElementById('btnResetP').addEventListener('click', () => {
  state.P = { u: 4.6, v: 1.7, w: 1.1 }; updateAll();
});

/* ── drag P ───────────────────────────────────────────────────────────── */
const _ndc = new THREE.Vector2();
const _rc = new THREE.Raycaster();
const _dragPlane = new THREE.Plane();
const _hit = new THREE.Vector3();
const _nrm = new THREE.Vector3();
let dragging = false;

function setNdc(e) {
  const r = canvas.getBoundingClientRect();
  _ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
}
window.addEventListener('pointerdown', (e) => {
  if (e.target !== canvas || state.panel === 'b') return;
  setNdc(e);
  _rc.setFromCamera(_ndc, camera);
  if (_rc.intersectObject(hitP, false).length) {
    dragging = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.stopPropagation();
    e.preventDefault();
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setNdc(e);
  camera.getWorldDirection(_nrm);
  _dragPlane.setFromNormalAndCoplanarPoint(_nrm, dotP.position);
  _rc.setFromCamera(_ndc, camera);
  if (_rc.ray.intersectPlane(_dragPlane, _hit)) {
    state.P.u = THREE.MathUtils.clamp(_hit.x, 1.2, 6.2);
    state.P.v = THREE.MathUtils.clamp(_hit.y, -2.4, 3.2);
    state.P.w = THREE.MathUtils.clamp(-_hit.z, -2.4, 3.0);
    updateAll();
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'grab'; }
});

/* ── guided demo ──────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1. The pinhole setup',
    text: 'World axes X, Y, Z meet at the pinhole (0,0,0). A scene point P out along +Z sends a ray through the pinhole onto the real projection plane a distance f behind it.',
    state: { panel: 'a', mode: 'real', f: 1.5 }
  },
  {
    title: '2. Why the image is inverted',
    text: 'On the real plane the green x and y axes point down-left: the image point p lands on the opposite side of the optical axis from P. Orbit the scene to see that ray as one straight line.',
    state: { panel: 'a', mode: 'real', f: 1.5 }
  },
  {
    title: '3. The virtual camera plane',
    text: 'Place an identical plane a distance f in front of the pinhole. The same ray hits it at the mirrored, upright location p = (fX/Z, fY/Z) — same geometry, no inversion.',
    state: { panel: 'a', mode: 'both', f: 1.5 }
  },
  {
    title: '4. Focal length rescales the image',
    text: 'Sliding f pushes both planes outward and magnifies p away from the principal point in exact proportion — the scale factor f in the projection equation.',
    state: { panel: 'linked', mode: 'both', f: 2.6 }
  },
  {
    title: '5. Camera vs pixel coordinates',
    text: 'Head-on, p has continuous camera coordinates (x,y) measured from the principal point and discrete pixel indices (n,m) measured from the image corner — the two differ by the principal-point offset.',
    state: { panel: 'b', mode: 'virt', f: 1.5 }
  }
];
let stepIdx = -1, playing = false, playTimer = null;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
  state.mode = s.state.mode; selMode.value = s.state.mode; applyMode();
  state.fTarget = s.state.f; rngF.value = String(s.state.f); fVal.textContent = s.state.f.toFixed(2);
  const panelChanged = state.panel !== s.state.panel;
  state.panel = s.state.panel; selPanel.value = s.state.panel;
  applyPanel(true);
  if (!panelChanged) refreshVis();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  playing = !playing;
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play';
  btnPlay.classList.toggle('active', playing);
  clearInterval(playTimer);
  if (playing) {
    goToStep(stepIdx + 1);
    playTimer = setInterval(() => {
      if (stepIdx >= steps.length - 1) {
        clearInterval(playTimer); playing = false;
        btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active');
      } else goToStep(stepIdx + 1);
    }, 5200);
  }
});
stepTitle.textContent = 'Press ▶ Play for the guided walkthrough';
stepText.textContent = 'Or explore freely: drag P, change f, and switch panels.';

/* ── per-frame updates (billboards, fades, f tween, panel-b labels) ───── */
let _tPrev = performance.now();
function figTick() {
  requestAnimationFrame(figTick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _tPrev) / 1000);
  _tPrev = now;

  if (Math.abs(state.f - state.fTarget) > 1e-4) {
    state.f += (state.fTarget - state.f) * Math.min(1, dt * 7);
    if (Math.abs(state.f - state.fTarget) < 1e-4) state.f = state.fTarget;
    rngF.value = String(state.f);
    fVal.textContent = state.f.toFixed(2);
    updateAll();
  }

  let fadeChanged = false;
  for (const k of ['real', 'virt']) {
    const st = sets[k];
    if (Math.abs(st.a - st.t) > 0.002) {
      st.a += (st.t - st.a) * Math.min(1, dt * 8);
      applyFade(st); fadeChanged = true;
    } else if (st.a !== st.t) {
      st.a = st.t; applyFade(st); fadeChanged = true;
    }
  }
  if (fadeChanged) refreshVis();

  for (const b of billboards) b.quaternion.copy(camera.quaternion);

  if (groupB.parent) {
    groupB.quaternion.copy(camera.quaternion);
    groupB.updateMatrixWorld(true);
    for (const e of bLabels) e.pos.copy(e.local).applyMatrix4(groupB.matrixWorld);
  }
}
figTick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

