<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (one line per element) ───────────────────────────────────
 world Z axis (optical)  → Cylinder r0.026 + Cone head, black, from pinhole u:0..6.2
 world Y axis            → Cylinder + Cone head, black, v:0..3.4
 world X axis (receding) → Cylinder + Cone head, black, w:0..3.0
 pinhole                 → SphereGeometry(0.1) black, at origin
 projection plane        → PlaneGeometry(2.6,2.6) fill #8a8a8a + EdgesGeometry LineDashed black, u=-f
 virtual camera plane    → PlaneGeometry(2.6,2.6) fill #eaf2f2 a0.55 + 4 tube border black, u=+f
 green in-plane axes     → Arrow (cylinder+cone) #00d200, len 1.1, on each plane (inverted on real)
 red focal arrows        → double-headed Arrow #ff0000 on optical axis, 0→-f and 0→+f
 scene point P           → billboard CircleGeometry black 0.1 + cyan 0.07
 drop lines from P       → thin Cylinders r0.012 #b0b0b0
 projection rays         → LineDashedMaterial #cfcfcf  [P,pV,O] and [O,pR]
 image points p          → billboard circles cyan, + gray drop line on virtual plane
 panel (b) frame         → 4 tubes r0.024 black, 3.2 x 2.4 (4:3), billboarded group
 panel (b) camera axes   → green arrows (y up, x left) from principal point
 panel (b) image axes    → blue #1414ff arrows (n right, m up) from bottom-left corner
 panel (b) point p       → billboard circles cyan
 all text                → addLabel HTML (serif italic for f,x,y,n,m; bold for P,p)
 CAMERA: orthographic, azimuth 60 / elevation 21.4  →  optical axis ~horizontal right,
         receding X up-right ~32 deg, Y vertical  (matches the source axonometric layout)
──────────────────────────────────────────────────────────────────────────── */

// figure coords (u = optical/Z, v = up/Y, w = receding/X) → world
const FC = (u, v, w) => new THREE.Vector3(u, v, -w);
const BLACK = 0x000000, GREEN = 0x00d200, RED = 0xff0000,
      CYAN = 0x55d6ee, BLUE = 0x1414ff, DASH = 0xcfcfcf, GRAY = 0xb0b0b0;

const VIEW_AZ = 60, VIEW_EL = 21.4;   // pose solved so Z is ~horizontal right, X up-right

const IT = s => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">${s}</span>`;
const BD = s => `<span style="font-weight:700">${s}</span>`;
const TX = s => `<span style="font-family:Georgia,'Times New Roman',serif">${s}</span>`;

/* ── generic builders ─────────────────────────────────────────────────── */
const YUP = new THREE.Vector3(0, 1, 0);

function segMesh(radius, color, opacity = 1) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity });
  const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10), mat);
  m.setEnds = (a, b) => {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = Math.max(dir.length(), 1e-5);
    const n = dir.clone().divideScalar(len);
    m.scale.set(1, len, 1);
    m.position.copy(a).addScaledVector(n, len / 2);
    m.quaternion.setFromUnitVectors(YUP, n);
  };
  return m;
}

function makeArrow(color, radius, headLen, double = false) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat);
  g.add(shaft); g.add(head);
  let head2 = null;
  if (double) { head2 = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat); g.add(head2); }
  const flip = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI);
  g.setEnds = (a, b) => {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = Math.max(dir.length(), 1e-4);
    const n = dir.clone().divideScalar(len);
    const q = new THREE.Quaternion().setFromUnitVectors(YUP, n);
    shaft.scale.set(1, len, 1);
    shaft.position.copy(a).addScaledVector(n, len / 2);
    shaft.quaternion.copy(q);
    head.position.copy(b).addScaledVector(n, -headLen / 2);
    head.quaternion.copy(q);
    if (head2) {
      head2.position.copy(a).addScaledVector(n, headLen / 2);
      head2.quaternion.copy(q.clone().multiply(flip));
    }
  };
  return g;
}

function makeDashed(color, dash = 0.14, gap = 0.11) {
  const mat = new THREE.LineDashedMaterial({ color, dashSize: dash, gapSize: gap, transparent: true });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  line.setPts = (pts) => {
    line.geometry.dispose();
    line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
    line.computeLineDistances();
  };
  line.setPts([new THREE.Vector3(), new THREE.Vector3(0, 0, 0.001)]);
  return line;
}

function makeDot(r, color) {
  const g = new THREE.Group();
  const outer = new THREE.Mesh(new THREE.CircleGeometry(r, 28),
    new THREE.MeshBasicMaterial({ color: BLACK, transparent: true, depthTest: false, depthWrite: false }));
  const inner = new THREE.Mesh(new THREE.CircleGeometry(r * 0.7, 28),
    new THREE.MeshBasicMaterial({ color, transparent: true, depthTest: false, depthWrite: false }));
  inner.position.z = 0.002;
  outer.renderOrder = 30; inner.renderOrder = 31;
  g.add(outer); g.add(inner);
  return g;
}

/* ── groups ───────────────────────────────────────────────────────────── */
const groupA = new THREE.Group();
const groupB = new THREE.Group();
scene.add(groupA);

const realGroup = new THREE.Group(); realGroup.rotation.y = Math.PI / 2; groupA.add(realGroup);
const virtGroup = new THREE.Group(); virtGroup.rotation.y = Math.PI / 2; groupA.add(virtGroup);

const billboards = [];

/* ── panel (a): world axes (Z axis starts AT the pinhole, positive side) ─ */
const axZ = makeArrow(BLACK, 0.026, 0.32);
axZ.setEnds(FC(0, 0, 0), FC(6.2, 0, 0)); groupA.add(axZ);
const axY = makeArrow(BLACK, 0.026, 0.32);
axY.setEnds(FC(0, 0, 0), FC(0, 3.4, 0)); groupA.add(axY);
const axX = makeArrow(BLACK, 0.026, 0.32);
axX.setEnds(FC(0, 0, 0), FC(0, 0, 3.0)); groupA.add(axX);

const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.1, 20, 16),
  new THREE.MeshBasicMaterial({ color: BLACK }));
groupA.add(pinhole);

/* ── planes ───────────────────────────────────────────────────────────── */
const SIDE = 2.6, H = SIDE / 2;

// real / projection plane (grey, dashed border)
const realMesh = new THREE.Mesh(new THREE.PlaneGeometry(SIDE, SIDE),
  new THREE.MeshBasicMaterial({ color: 0x8a8a8a, side: THREE.DoubleSide, transparent: true, opacity: 0.95, depthWrite: false }));
