<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (one line per element) ───────────────────────────────────
 world Z axis (optical) → Cylinder r0.026 + Cone head, black, 0 → +6.2 z
 world Y axis           → Cylinder r0.026 + Cone head, black, 0 → +3.4 y
 world X axis (receding)→ Cylinder r0.026 + Cone head, black, 0 → +3.0 x
 pinhole                → SphereGeometry(0.1) black at origin
 projection plane       → PlaneGeometry(2.6,2.6) fill #8a8a8a, z=-f, DoubleSide
 projection border      → thick dash cylinders r0.024 black (dash .24/gap .15)
 virtual camera plane   → PlaneGeometry(2.6,2.6) fill #eaf2f2 a.55, z=+f
 virtual border         → 4 solid tubes r0.021 black
 green in-plane axes    → Arrow (cyl+cone) #00d200 len 1.1: +X,+Y on virtual; -X,-Y on real
 red focal arrows       → double-headed Arrow #ff0000 on Z axis, 0→-f and 0→+f
 scene point P          → billboard disc black r0.1 + cyan r0.07
 drop lines from P      → Cylinders r0.012 #b0b0b0 (P→(x,0,z)→(0,0,z))
 projection rays        → THICK dashed cylinder chains #9a9a9a: P→O and O→p_real
 image points p         → billboard cyan discs + short gray drop on virtual plane
 panel (b) frame        → 4 tubes r0.025 black, 3.4 × 2.55 (4:3), billboarded group
 panel (b) camera axes  → green arrows (y up, x LEFT) from principal point
 panel (b) image axes    → blue #1414ff arrows (n right, m up) from bottom-left corner
 panel (b) point p      → billboard cyan disc
 all text               → addLabel, Times serif, lining numerals; italic f,x,y,n,m; bold P,p
 CAMERA: orthographic azimuth 159° / elevation 18.7°  →  Z axis ≈ horizontal right (−6°),
         X axis up-right ≈ 40°, Y vertical  (matches the printed axonometric)
──────────────────────────────────────────────────────────────────────────── */

const V = (x, y, z) => new THREE.Vector3(x, y, z);
const BLACK = 0x000000, GREEN = 0x00d200, RED = 0xff0000,
  CYAN = 0x55d6ee, BLUE = 0x1414ff, RAYC = 0x9a9a9a, GRAY = 0xb0b0b0;

const VIEW_AZ = 159, VIEW_EL = 18.7;

const SER = "font-family:'Times New Roman',Times,serif;font-variant-numeric:lining-nums";
const TX = s => `<span style="${SER}">${s}</span>`;
const IT = s => `<span style="${SER};font-style:italic">${s}</span>`;
const BD = s => `<span style="${SER};font-weight:700">${s}</span>`;

/* ── generic builders ─────────────────────────────────────────────────── */
const YUP = V(0, 1, 0);
function setCylEnds(m, a, b) {
  const dir = b.clone().sub(a);
  const len = Math.max(dir.length(), 1e-5);
  const n = dir.divideScalar(len);
  m.scale.set(1, len, 1);
  m.position.copy(a).addScaledVector(n, len / 2);
  m.quaternion.setFromUnitVectors(YUP, n);
}
function segMesh(radius, color, opacity = 1) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity });
  const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10), mat);
  m.setEnds = (a, b) => setCylEnds(m, a, b);
  return m;
}
function makeArrow(color, radius, headLen, double = false) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat);
  g.add(shaft, head);
  let head2 = null;
  if (double) { head2 = new THREE.Mesh(new THREE.ConeGeometry(radius * 3.1, headLen, 16), mat); g.add(head2); }
  const flip = new THREE.Quaternion().setFromAxisAngle(V(1, 0, 0), Math.PI);
  g.setEnds = (a, b) => {
    const dir = b.clone().sub(a);
    const len = Math.max(dir.length(), 1e-4);
    const n = dir.clone().divideScalar(len);
    const q = new THREE.Quaternion().setFromUnitVectors(YUP, n);
    shaft.scale.set(1, len, 1);
    shaft.position.copy(a).addScaledVector(n, len / 2);
    shaft.quaternion.copy(q);
    head.position.copy(b).addScaledVector(n, -headLen / 2);
    head.quaternion.copy(q);
    if (head2) {
      head2.position.copy(a).addScaledVector(n, headLen / 2);
      head2.quaternion.copy(q.clone().multiply(flip));
    }
  };
  return g;
}
// thick, clearly visible dashed line built from cylinder dashes (pooled)
function makeDashLine(color, radius, dash, gap, maxN) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 8);
  const pool = [];
  for (let i = 0; i < maxN; i++) { const m = new THREE.Mesh(geo, mat); m.visible = false; g.add(m); pool.push(m); }
  g.setSeg = (a, b) => {
    const dir = b.clone().sub(a);
    const len = dir.length();
    let i = 0;
    if (len > 1e-6) {
      const n = dir.clone().divideScalar(len);
      let t = 0;
      while (t < len - 1e-6 && i < maxN) {
        const dl = Math.min(dash, len - t);
        setCylEnds(pool[i], a.clone().addScaledVector(n, t), a.clone().addScaledVector(n, t + dl));
        pool[i].visible = true; i++; t += dash + gap;
      }
    }
    for (; i < maxN; i++) pool[i].visible = false;
  };
  return g;
}
function staticDashes(parent, a, b, radius, mat, dash, gap) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  const n = dir.clone().divideScalar(len);
  let t = 0;
  while (t < len - 1e-6) {
    const dl = Math.min(dash, len - t);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 8), mat);
    setCylEnds(m, a.clone().addScaledVector(n, t), a.clone().addScaledVector(n, t + dl));
    parent.add(m);
    t += dash + gap;
  }
}
function makeDot(r, color) {
  const g = new THREE.Group();
  const outer = new THREE.Mesh(new THREE.CircleGeometry(r, 28),
    new THREE.MeshBasicMaterial({ color: BLACK, transparent: true, depthTest: false, depthWrite: false }));
  const inner = new THREE.Mesh(new THREE.CircleGeometry(r * 0.68, 28),
    new THREE.MeshBasicMaterial({ color, transparent: true, depthTest: false, depthWrite: false }));
  inner.position.z = 0.002;
  outer.renderOrder = 30; inner.renderOrder = 31;
  g.add(outer, inner);
  return g;
}

/* ── groups ───────────────────────────────────────────────────────────── */
const groupA = new THREE.Group();
const groupB = new THREE.Group();
scene.add(groupA);
const realGroup = new THREE.Group(); groupA.add(realGroup);
const virtGroup = new THREE.Group(); groupA.add(virtGroup);
const billboards = [];

/* ── panel (a): world axes ────────────────────────────────────────────── */
