/* ── fade sets ────────────────────────────────────────────────────────── */
function collect(o, arr) {
  o.traverse(n => {
    if (!n.material) return;
    const ms = Array.isArray(n.material) ? n.material : [n.material];
    ms.forEach(m => {
      if (arr.indexOf(m) === -1) {
        m.transparent = true;
        if (m.userData.base === undefined) m.userData.base = m.opacity;
        arr.push(m);
      }
    });
  });
  return arr;
}
const sets = {
  real: { mats: [], labels: ['projPlane', 'rx', 'ry', 'pR', 'fL'], a: 1, t: 1 },
  virt: { mats: [], labels: ['virtPlane', 'vx', 'vy', 'pV', 'fR'], a: 1, t: 1 }
};
collect(realGroup, sets.real.mats); collect(dotPR, sets.real.mats);
collect(fArrowL, sets.real.mats); collect(rayReal, sets.real.mats);
collect(virtGroup, sets.virt.mats); collect(dotPV, sets.virt.mats);
collect(pDrop, sets.virt.mats); collect(fArrowR, sets.virt.mats);
function applyFade(set) {
  for (const m of set.mats) m.opacity = (m.userData.base === undefined ? 1 : m.userData.base) * set.a;
}

/* ── state + update ───────────────────────────────────────────────────── */
const state = { f: 1.5, fTarget: 1.5, P: { x: 1.1, y: 1.7, z: 4.6 }, panel: 'a', mode: 'both' };
const readout = document.getElementById('readout');

function refreshVis() {
  const showA = state.panel !== 'b';
  const showB = state.panel !== 'a';
  for (const e of LABELS) {
    let on = e.group === 'A' ? showA : showB;
    if (on && e.set) on = sets[e.set].a > 0.08;
    e.div.style.visibility = on ? 'visible' : 'hidden';
  }
}

function updateAll() {
  const f = state.f, X = state.P.x, Y = state.P.y, Z = state.P.z;
  realGroup.position.z = -f; virtGroup.position.z = f;
  realGroup.updateMatrixWorld(true); virtGroup.updateMatrixWorld(true);

  fArrowL.setEnds(V(0, 0, 0), V(0, 0, -f));
  fArrowR.setEnds(V(0, 0, 0), V(0, 0, f));

  const Pw = V(X, Y, Z);
  const xc = f * X / Z, yc = f * Y / Z;
  const pV = V(xc, yc, f);
  const pR = V(-xc, -yc, -f);

  dotP.position.copy(Pw); hitP.position.copy(Pw);
  dotPV.position.copy(pV); dotPR.position.copy(pR);
  rayMain.setSeg(Pw, V(0, 0, 0));          // passes exactly through p on the virtual plane
  rayReal.setSeg(V(0, 0, 0), pR);          // same straight line, continued past the pinhole
  dropV.setEnds(Pw, V(X, 0, Z));
  dropH.setEnds(V(X, 0, Z), V(0, 0, Z));
  pDrop.setEnds(pV, V(xc, 0, f));

  L.fL.pos.set(0, 0, -f / 2); L.fR.pos.set(0, 0, f / 2);
  L.projPlane.pos.set(-1.3, -1.45, -f); L.virtPlane.pos.set(-0.3, -1.45, f);
  L.vx.pos.set(GLEN, 0, f); L.vy.pos.set(0, GLEN, f);
  L.rx.pos.set(-GLEN, 0, -f); L.ry.pos.set(0, -GLEN, -f);
  L.P.pos.copy(Pw); L.pV.pos.copy(pV); L.pR.pos.copy(pR);
  L.panelA.pos.set(0, -2.95, Math.max(1.6, f));

  const s = BW / SIDE;
  dotB.position.set(B_ORG.x - xc * s, B_ORG.y + yc * s, 0.03);
  L.bp.local.set(dotB.position.x, dotB.position.y, 0.03);

  const px = SIDE / 640;                    // 2.6 world units ↔ 640 px
  const n = Math.round(380 - xc / px), m = Math.round(300 + yc / px);
  readout.innerHTML =
    `<b>P</b> = (X ${X.toFixed(2)}, Y ${Y.toFixed(2)}, Z ${Z.toFixed(2)})<br>` +
    `<b>p</b> cam = (x ${xc.toFixed(3)}, y ${yc.toFixed(3)})<br>` +
    `<b>p</b> pix = (n ${n}, m ${m})<br>` +
    `f = ${f.toFixed(2)}`;
}

/* ── panel switching ──────────────────────────────────────────────────── */
const _camRight = new THREE.Vector3(), _camUp = new THREE.Vector3();
function placePanelB() {
  if (state.panel === 'linked') {
    _camRight.set(1, 0, 0).applyQuaternion(camera.quaternion);
    _camUp.set(0, 1, 0).applyQuaternion(camera.quaternion);
    groupB.position.copy(_camRight).multiplyScalar(8.7).addScaledVector(_camUp, 0.25);
  } else {
    groupB.position.set(0, 0, 0);
  }
  groupB.quaternion.copy(camera.quaternion);
  groupB.updateMatrixWorld(true);
  for (const e of bLabels) e.pos.copy(e.local).applyMatrix4(groupB.matrixWorld);
}

function applyPanel(refit = true) {
  const needA = state.panel !== 'b';
  const needB = state.panel !== 'a';
  if (needA && !groupA.parent) scene.add(groupA);
  if (!needA && groupA.parent) scene.remove(groupA);
  if (needB && !groupB.parent) scene.add(groupB);
  if (!needB && groupB.parent) scene.remove(groupB);
  updateAll();
  placePanelB();
  if (refit) {
    if (state.panel === 'b') {
      setCameraView({ projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, heightFraction: 0.82 });
    } else {
      setCameraView({
        projection: 'orthographic', azimuthDeg: VIEW_AZ, elevationDeg: VIEW_EL, rollDeg: 0,
        heightFraction: state.panel === 'linked' ? 0.66 : 0.62
      });
    }
    placePanelB();
  }
  refreshVis();
}

function applyMode() {
  sets.real.t = (state.mode === 'virt') ? 0 : 1;
  sets.virt.t = (state.mode === 'real') ? 0 : 1;
}

